{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE luggage_master COPY GRANTS AS WITH store_master AS ( SELECT branch_code, \"Shipping Address City\" AS CITY, state AS STATE, \"Shipping Address Pincode\" AS PINCODE FROM GS_STORE_DETAILS QUALIFY ROW_NUMBER() OVER ( PARTITION BY branch_code ORDER BY ( IFF(\"Shipping Address City\" IS NOT NULL, 1, 0) + IFF(state IS NOT NULL, 1, 0) + IFF(\"Shipping Address Pincode\" IS NOT NULL, 1, 0) ) DESC, \"Shipping Address City\" NULLS LAST, state NULLS LAST, \"Shipping Address Pincode\" NULLS LAST ) = 1 ), offline AS ( SELECT o.ORDER_DATE, TO_VARCHAR(o.branch_code) AS MARKETPLACE, UPPER(TRIM(o.MARKETPLACE_MAPPED)) AS MARKETPLACE_MAPPED, TO_VARCHAR(o.phone) AS phone, o.order_timestamp, o.order_name AS Order_id, o.SKU, o.sku_group, CASE WHEN o.SKU LIKE \'4MTL0001%\' THEN \'BLINK\' WHEN o.SKU LIKE \'4MTL0002%\' THEN \'VITO\' WHEN o.SKU LIKE \'4MTL0003%\' THEN \'RUBIK\' ELSE \'Other\' END AS Style, CASE WHEN RIGHT(o.SKU, 2) = \'S3\' THEN \'SET-3\' WHEN RIGHT(o.SKU, 2) = \'S2\' THEN \'SET-2\' ELSE RIGHT(o.SKU, 1) END AS SIZE, RIGHT(LEFT(o.SKU, 11), 2) AS COLOR, s.CITY, s.STATE, TO_VARCHAR(s.PINCODE) AS PINCODE, o.SUBORDER_QUANTITY AS QTY, o.MRP, ROUND(o.SELLING_PRICE, 0) AS SELLING_PRICE, o.COGS_PRICE AS COGS, ROUND(o.SELLING_PRICE, 0) - o.COGS_PRICE AS GROSS_PROFIT, \'\' AS shippingpackagecode, \'\' AS shippingpackagestatus, \'\' AS shipping_courier, CAST(NULL AS DATE) AS delivered_date, \'\' AS AWB, \'\' AS warehouse_name, CAST(NULL AS VARCHAR) AS order_status, CAST(NULL AS VARCHAR) AS sale_order_item_status, \'OFFLINE\' AS source_channel FROM snitch_db.maplemonk.store_fact_items_offline o LEFT JOIN store_master s ON o.branch_code = s.branch_code WHERE o.sku_group LIKE \'4MTL0%\' AND o.doc_prefix NOT ILIKE \'%QCOM%\' AND o.doc_prefix NOT ILIKE \'%OMS%\' AND COALESCE( UPPER(TRIM(o.MARKETPLACE_MAPPED)), \'\' ) <> \'SHOPIFY\' ), online AS ( SELECT order_date, TO_VARCHAR(marketplace) AS marketplace, UPPER(TRIM(marketplace_mapped)) AS marketplace_mapped, CAST(NULL AS VARCHAR) AS phone, order_timestamp, order_name AS Order_id, sku, sku_group, CASE WHEN sku LIKE \'4MTL0001%\' THEN \'BLINK\' WHEN sku LIKE \'4MTL0002%\' THEN \'VITO\' WHEN sku LIKE \'4MTL0003%\' THEN \'RUBIK\' ELSE \'Other\' END AS Style, CASE WHEN RIGHT(sku, 2) = \'S3\' THEN \'SET-3\' WHEN RIGHT(sku, 2) = \'S2\' THEN \'SET-2\' ELSE RIGHT(sku, 1) END AS SIZE, RIGHT(LEFT(sku, 11), 2) AS COLOR, city, state, TO_VARCHAR(pincode) AS pincode, suborder_quantity AS QTY, mrp, selling_price AS SELLING_PRICE, cost AS COGS, selling_price - cost AS GROSS_PROFIT, shippingpackagecode, shippingpackagestatus, shipping_courier, delivered_date, AWB, warehouse_name, order_status, sale_order_item_status, \'ONLINE\' AS source_channel FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate WHERE sku_group LIKE \'4MTL0%\' AND UPPER(TRIM(marketplace_mapped)) = \'SHOPIFY\' ), combined_raw AS ( SELECT * FROM offline UNION ALL SELECT * FROM online ), combined AS ( SELECT c.*, COALESCE( TO_VARCHAR(TRY_TO_NUMBER(c.MARKETPLACE)), TRIM(c.MARKETPLACE) ) AS store_key, NULLIF(TRIM(c.phone), \'\') AS phone_key, UPPER(TRIM(c.SKU)) AS sku_key, UPPER(TRIM(c.ORDER_ID)) AS order_key, ROW_NUMBER() OVER ( ORDER BY c.source_channel, c.ORDER_DATE, c.ORDER_TIMESTAMP, c.ORDER_ID, c.SKU, c.MARKETPLACE, c.phone, c.QTY, c.MRP, c.SELLING_PRICE, c.COGS, c.AWB, c.sale_order_item_status ) AS combined_row_id FROM combined_raw c ), cp_base AS ( SELECT DISTINCT UPPER(TRIM(TO_VARCHAR(ORDER_ID))) AS order_key, awb_number, pre_current_status, UPPER(TRIM(status)) AS status, quantity_in_box, courier_partner, return_reason, sku_list, UPPER(TRIM(journey)) AS journey FROM cp_1 WHERE SKU_LIST ILIKE \'%4MTL0%\' AND NOT ( COALESCE(UPPER(TRIM(journey)), \'\') IN (\'RTO\', \'REVERSE\') AND COALESCE(UPPER(TRIM(status)), \'\') = \'CANCELLED\' ) ), online_order_skus AS ( SELECT DISTINCT order_key, sku_key FROM combined WHERE source_channel = \'ONLINE\' ), cp_matched AS ( SELECT c.order_key, c.sku_key, cp.awb_number, cp.pre_current_status, cp.status, cp.quantity_in_box, cp.courier_partner, cp.return_reason, cp.sku_list, cp.journey FROM online_order_skus c INNER JOIN cp_base cp ON c.order_key = cp.order_key AND POSITION( \',\' || c.sku_key || \',\' IN \',\' || UPPER(REPLACE(cp.sku_list, \' \', \'\')) || \',\' ) > 0 QUALIFY ROW_NUMBER() OVER ( PARTITION BY c.order_key, c.sku_key ORDER BY CASE WHEN cp.journey IN (\'RTO\', \'REVERSE\') THEN 0 ELSE 1 END, CASE WHEN cp.status = \'DELIVERED\' THEN 0 WHEN cp.status = \'INTRANSIT\' THEN 1 WHEN cp.status = \'PENDING\' THEN 2 WHEN cp.status = \'ORDER_PLACED\' THEN 3 ELSE 4 END, cp.awb_number NULLS LAST, cp.journey, cp.status, cp.sku_list, cp.pre_current_status, cp.quantity_in_box, cp.courier_partner, cp.return_reason ) = 1 ), final_data AS ( SELECT c.*, m.awb_number, m.pre_current_status, m.status, m.quantity_in_box, m.courier_partner, m.return_reason, m.sku_list, CASE WHEN m.journey = \'REVERSE\' THEN \'Reverse\' WHEN m.journey = \'FORWARD\' THEN \'Forward\' ELSE m.journey END AS journey, CASE WHEN m.journey = \'RTO\' THEN \'RTO\' WHEN m.journey = \'REVERSE\' AND m.status IN ( \'DELIVERED\', \'INTRANSIT\', \'PENDING\', \'ORDER_PLACED\' ) THEN \'RETURNED\' WHEN m.journey = \'REVERSE\' THEN m.status WHEN UPPER(c.sale_order_item_status) = \'CANCELLED\' THEN \'CANCELLED\' WHEN m.journey = \'FORWARD\' THEN m.status ELSE c.sale_order_item_status END AS online_final_status FROM combined c LEFT JOIN cp_matched m ON c.source_channel = \'ONLINE\' AND c.order_key = m.order_key AND c.sku_key = m.sku_key ), store_returns_base AS ( SELECT COALESCE( TO_VARCHAR( TRY_TO_NUMBER(TO_VARCHAR(branch_code)) ), TRIM(TO_VARCHAR(branch_code)) ) AS store_key, NULLIF(TRIM(TO_VARCHAR(phone)), \'\') AS phone_key, UPPER(TRIM(sku)) AS sku_key, order_timestamp AS return_timestamp, SUM( COALESCE(suborder_quantity, 1) ) AS return_qty FROM snitch_db.maplemonk.store_returns_fact_items_final_check WHERE sku ILIKE \'4MTL0%\' AND marketplace NOT ILIKE \'%WH%\' AND order_id NOT ILIKE \'%RTO%\' AND order_timestamp IS NOT NULL AND NULLIF(TRIM(TO_VARCHAR(phone)), \'\') IS NOT NULL GROUP BY 1, 2, 3, 4 HAVING SUM( COALESCE(suborder_quantity, 1) ) > 0 ), store_sales_bills AS ( SELECT store_key, phone_key, sku_key, order_key, MAX(order_timestamp) AS sales_timestamp, SUM(QTY) AS sales_qty FROM final_data WHERE source_channel = \'OFFLINE\' AND phone_key IS NOT NULL AND order_timestamp IS NOT NULL AND order_key IS NOT NULL AND QTY > 0 GROUP BY store_key, phone_key, sku_key, order_key ), return_candidates AS ( SELECT sr.store_key, sr.phone_key, sr.sku_key, sr.return_timestamp, sr.return_qty, sb.order_key AS sales_order_key, sb.sales_timestamp, sb.sales_qty FROM store_returns_base sr INNER JOIN store_sales_bills sb ON sr.store_key = sb.store_key AND sr.phone_key = sb.phone_key AND sr.sku_key = sb.sku_key AND sb.sales_timestamp < sr.return_timestamp QUALIFY ROW_NUMBER() OVER ( PARTITION BY sr.store_key, sr.phone_key, sr.sku_key, sr.return_timestamp ORDER BY sb.sales_timestamp DESC, sb.order_key DESC ) = 1 ), return_by_bill AS ( SELECT store_key, phone_key, sku_key, sales_order_key, SUM(return_qty) AS matched_return_qty FROM return_candidates GROUP BY store_key, phone_key, sku_key, sales_order_key ), return_allocation_base AS ( SELECT fd.*, COALESCE( rb.matched_return_qty, 0 ) AS matched_return_qty, COALESCE( SUM(GREATEST(COALESCE(fd.QTY, 0), 0)) OVER ( PARTITION BY fd.source_channel, fd.store_key, fd.phone_key, fd.order_key, fd.sku_key ORDER BY fd.order_timestamp, fd.combined_row_id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ), 0 ) AS previous_sales_qty FROM final_data fd LEFT JOIN return_by_bill rb ON fd.source_channel = \'OFFLINE\' AND fd.store_key = rb.store_key AND fd.phone_key = rb.phone_key AND fd.sku_key = rb.sku_key AND fd.order_key = rb.sales_order_key ), return_allocation AS ( SELECT ra.*, CASE WHEN ra.source_channel = \'OFFLINE\' THEN GREATEST( 0, LEAST( COALESCE(ra.QTY, 0), ra.matched_return_qty - ra.previous_sales_qty ) ) ELSE 0 END AS STORE_RETURN_QTY FROM return_allocation_base ra ), classified AS ( SELECT ra.*, CASE WHEN source_channel = \'OFFLINE\' AND STORE_RETURN_QTY > 0 AND STORE_RETURN_QTY >= QTY THEN \'RETURNED\' WHEN source_channel = \'OFFLINE\' AND STORE_RETURN_QTY > 0 AND STORE_RETURN_QTY < QTY THEN \'PARTIALLY_RETURNED\' WHEN source_channel = \'OFFLINE\' THEN \'NET\' ELSE online_final_status END AS final_status FROM return_allocation ra ), quantity_calculation AS ( SELECT c.*, COALESCE(QTY, 0) AS GROSS_QTY, CASE WHEN source_channel = \'OFFLINE\' THEN COALESCE(QTY, 0) - STORE_RETURN_QTY WHEN journey IN (\'Reverse\', \'RTO\') THEN 0 WHEN final_status IN ( \'DELIVERED\', \'INTRANSIT\', \'ORDER_PLACED\', \'PACKED\' ) THEN COALESCE(QTY, 0) ELSE 0 END AS NET_QTY FROM classified c ), output_data AS ( SELECT qc.*, GROSS_QTY - NET_QTY AS GROSS_ONLY_QTY, CASE WHEN NET_QTY > 0 THEN \'NET\' ELSE \'GROSS_ONLY\' END AS SALES_TYPE FROM quantity_calculation qc ) SELECT od.* EXCLUDE ( store_key, phone_key, sku_key, order_key, online_final_status, matched_return_qty, previous_sales_qty ) FROM output_data od where UPPER(TRIM(MARKETPLACE_MAPPED)) NOT IN (\'TEST WAREHOUSE\', \'SNITCH - WH - NORTH\') ORDER BY od.ORDER_DATE DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            